import { House } from './house.js';
const checks = [];
const eq = (label, got, want) => checks.push([label, JSON.stringify(got) === JSON.stringify(want)]);
eq('verse(1)', House.verse(1), ['This is the house that Jack built.']);
eq('verses(1,1)', House.verses(1, 1), ['This is the house that Jack built.']);
eq('verses(12,12) len', House.verses(12, 12), House.verse(12));
for (let n = 1; n <= 12; n += 1) eq(`verse(${n}) lines=${n}`, House.verse(n).length, n);
for (let n = 1; n <= 12; n += 1) {
  const v = House.verse(n);
  eq(`verse(${n}) first`, v[0], `This is the ${['house that Jack built.','malt','rat','cat','dog','cow with the crumpled horn','maiden all forlorn','man all tattered and torn','priest all shaven and shorn','rooster that crowed in the morn','farmer sowing his corn','horse and the hound and the horn'][n-1]}`);
  eq(`verse(${n}) last`, v[v.length - 1], 'that lay in the house that Jack built.');
}
// verses(2,3) blank separator
eq('verses(2,3)', House.verses(2, 3), [...House.verse(2), '', ...House.verse(3)]);
// no null/undefined leaking
const all = House.verses(1, 12).join('\n');
checks.push(['no null/undefined', !/null|undefined/.test(all)]);
// endVerse < startVerse -> empty
eq('verses(5,4)', House.verses(5, 4), []);
const fails = checks.filter(([, ok]) => !ok);
console.log(`edge checks: ${checks.length}, failures: ${fails.length}`);
fails.forEach(([l]) => console.log('FAIL', l));
process.exit(fails.length ? 1 : 0);
